package com.ncdex.instrument.config;import org.springframework.context.annotation.*;import org.springframework.data.redis.connection.RedisConnectionFactory;import org.springframework.data.redis.core.RedisTemplate;import org.springframework.data.redis.serializer.*;@Configuration public class RedisConfig{@Bean RedisTemplate<String,Object> redisTemplate(RedisConnectionFactory factory){RedisTemplate<String,Object> t=new RedisTemplate<>();t.setConnectionFactory(factory);t.setKeySerializer(new StringRedisSerializer());t.setHashKeySerializer(new StringRedisSerializer());var json=new GenericJackson2JsonRedisSerializer();t.setValueSerializer(json);t.setHashValueSerializer(json);t.afterPropertiesSet();return t;}}